function main(p, state) {
  const target = p.item;
  const want = (typeof p.count === 'number' && p.count > 0) ? p.count : 1;
  const c = state.container || {};
  const cslots = c.slots || [];
  const RESULT = 0;
  const GRID_FIRST = 1;
  const GRID_LAST = 9;
  const PLAYER_FROM = 10;
  const isOpen = !!(c.type && typeof c.type === 'string' && !/^none$/.test(c.type));

  let have = 0;
  let gridDirty = false;
  let resultItem = '';

  if (isOpen) {
    for (let i = 0; i < cslots.length; i++) {
      const s = cslots[i];
      if (!s || !s.id || typeof s.slot !== 'number') continue;
      if (s.slot === RESULT) resultItem = s.id;
      else if (s.slot >= GRID_FIRST && s.slot <= GRID_LAST) gridDirty = true;
      else if (s.slot >= PLAYER_FROM && s.id === target) have += (s.count || 0);
    }
  } else {
    const islots = (state.inventory && state.inventory.slots) || [];
    for (let i = 0; i < islots.length; i++) {
      const s = islots[i];
      if (s && s.id === target) have += (s.count || 0);
    }
  }

  const done = have >= want;
  let reason = '';
  if (!done) {
    if (resultItem) reason = 'result slot still holds ' + resultItem;
    else if (gridDirty) reason = 'crafting grid still has items, recipe not completed';
    else reason = 'no ' + target + ' in player slots';
  }
  return { done: done, have: have, gridDirty: gridDirty, resultItem: resultItem, reason: reason };
}
